#!/usr/bin/env python3
"""Original MIT SH-2 line-color/CRAM-coefficient fixture, adjacent LICENSE.

ST-058-R2 §§6.4/7.1/11.3/12.1. The guest populates every bitmap,
palette, coefficient, matrix and line-table byte through real bus writes.
No firmware, SDK routines, emulator code or external assets.
"""
import argparse
import hashlib
from pathlib import Path
import struct
from build_effects import assembler, store

HERE = Path(__file__).resolve().parent


def build():
    source = '; Original MIT line-color/CRAM-coefficient guest. Generated by build_line_color.py.\n'
    for off, value in [(0xE, 0x9000), (0x20, 0x10), (0x2A, 0x3200),
                       (0xFC, 4), (0xB4, 0x15), (0xB6, 7),
                       (0xE8, 0x10), (0xEC, 0x210), (0x10C, 7), (0x10E, 15)]:
        source += store(0x25F80000 + off, value)
    for off, value in [(0xBC, 0x20000), (0xA8, 0x80030000), (0xAC, 0x38000)]:
        source += store(0x25F80000 + off, value, 'l')
    for off in [0x10, 0x14, 0x1C, 0x2C, 0x4C, 0x50, 0x5C]:
        source += store(0x25E40000 + off, 0x10000, 'l')
    for y in range(2):
        for x, value in enumerate([0x801F, 0x83E0, 0xFC00, 0xFFFF]):
            source += store(0x25E00000 + (y * 512 + x) * 2, value)
        source += store(0x25E60000 + y * 2, 0x180 if y == 0 else 0x200)
    for index, value in [(0x181, 0x7C00), (0x182, 0x1F), (0x183, 0x3E0),
                         (0x201, 0x3E0), (0x202, 0x7C00), (0x203, 0x1F)]:
        source += store(0x25F00000 + index * 2, value)
    for x, value in enumerate([0x01010000, 0x02010000, 0x03010000, 0x80010000]):
        source += store(0x25F00800 + x * 4, value, 'l')
    source += store(0x25F80000, 0x8000)
    source += store(0x0600A200, 0x600D, 'l') + 'park:\nsleep\nbra park\nnop\n'
    code = assembler.assemble(source, base=0x200)
    assert len(code) < 0x10000
    rom = bytearray(524288)
    rom[:8] = struct.pack('>II', 0x200, 0x06100000)
    rom[0x200:0x200+len(code)] = code
    lines = ['# Original MIT line-color/CRAM-coefficient BIOS fixture. Adjacent LICENSE.',
             '# Generated from line-color.s by build_line_color.py; unspecified bytes zero.']
    for at in range(0, len(rom), 16):
        chunk = rom[at:at+16]
        if any(chunk):
            lines.append(f'{at:04X} ' + ' '.join(f'{w:04X}' for w in struct.unpack('>8H', chunk)))
    return source, '\n'.join(lines)+'\n', hashlib.sha256(rom).hexdigest()


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    source, text, digest = build()
    for path, value in [(HERE/'line-color.s', source), (HERE/'line-color.hex', text)]:
        if args.check:
            assert path.read_text() == value, f'Rebuild {path.name}'
        else:
            path.write_text(value)
    print(f'{"Verified" if args.check else "Built"} line-color.hex; expanded ROM SHA-256 {digest}')
